CREATE TYPE public.app_role AS ENUM ('super_admin','editor');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_self ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid()); CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.is_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) $$;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'super_admin'));
CREATE POLICY profiles_staff ON public.profiles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin'));
CREATE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name','Reader'),100)); RETURN NEW; END $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE FUNCTION public.assign_initial_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email='amirralli123890@gmail.com' AND NEW.email_confirmed_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE role='super_admin') THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'super_admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER initial_admin_verified AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_initial_admin();
CREATE TABLE public.categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), slug text UNIQUE NOT NULL CHECK(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), description text NOT NULL DEFAULT '', image_url text, sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.categories TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role; ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY category_read ON public.categories FOR SELECT TO anon,authenticated USING(true); CREATE POLICY category_manage ON public.categories FOR ALL TO authenticated USING(public.has_role(auth.uid(),'super_admin')) WITH CHECK(public.has_role(auth.uid(),'super_admin'));
CREATE TABLE public.articles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 250), slug text UNIQUE NOT NULL CHECK(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), description text NOT NULL DEFAULT '', content text NOT NULL DEFAULT '', category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL, author_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, author_name text NOT NULL DEFAULT 'Roxana Digital World', featured_image text, image_alt text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), featured boolean NOT NULL DEFAULT false, trending boolean NOT NULL DEFAULT false, seo_title text NOT NULL DEFAULT '', meta_description text NOT NULL DEFAULT '', focus_keywords text NOT NULL DEFAULT '', reading_time integer NOT NULL DEFAULT 1 CHECK(reading_time>0), price_usd numeric(12,2) CHECK(price_usd>=0), price_pkr numeric(12,2) CHECK(price_pkr>=0), published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.articles TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.articles TO authenticated; GRANT ALL ON public.articles TO service_role; ALTER TABLE public.articles ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_read ON public.articles FOR SELECT TO anon,authenticated USING(status='published'); CREATE POLICY staff_read ON public.articles FOR SELECT TO authenticated USING(public.is_staff()); CREATE POLICY staff_write ON public.articles FOR ALL TO authenticated USING(public.is_staff()) WITH CHECK(public.is_staff());
CREATE INDEX articles_published ON public.articles(status,published_at DESC); CREATE INDEX articles_category ON public.articles(category_id,status); CREATE INDEX articles_search ON public.articles USING gin(to_tsvector('english',title||' '||description));
CREATE TABLE public.comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), article_id uuid NOT NULL REFERENCES public.articles(id) ON DELETE CASCADE, parent_id uuid REFERENCES public.comments(id) ON DELETE CASCADE, user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), content text NOT NULL CHECK(length(content) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.comments TO anon; GRANT SELECT,DELETE ON public.comments TO authenticated; GRANT ALL ON public.comments TO service_role; ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY comments_public ON public.comments FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.articles WHERE id=article_id AND status='published')); CREATE POLICY comments_staff ON public.comments FOR ALL TO authenticated USING(public.is_staff()) WITH CHECK(public.is_staff());
CREATE TABLE public.comment_contacts (comment_id uuid PRIMARY KEY REFERENCES public.comments(id) ON DELETE CASCADE, email text NOT NULL CHECK(length(email)<=255)); GRANT ALL ON public.comment_contacts TO service_role; ALTER TABLE public.comment_contacts ENABLE ROW LEVEL SECURITY;
CREATE INDEX comments_article ON public.comments(article_id,created_at);
CREATE TABLE public.contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), email text NOT NULL CHECK(length(email)<=255), subject text NOT NULL CHECK(length(subject) BETWEEN 1 AND 200), message text NOT NULL CHECK(length(message) BETWEEN 1 AND 5000), read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.contact_messages TO authenticated; GRANT ALL ON public.contact_messages TO service_role; ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY; CREATE POLICY contact_admin ON public.contact_messages FOR ALL TO authenticated USING(public.has_role(auth.uid(),'super_admin')) WITH CHECK(public.has_role(auth.uid(),'super_admin'));
CREATE TABLE public.site_settings (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), instagram_url text NOT NULL DEFAULT '', facebook_url text NOT NULL DEFAULT '', youtube_url text NOT NULL DEFAULT '', tiktok_url text NOT NULL DEFAULT '', x_url text NOT NULL DEFAULT '', pinterest_url text NOT NULL DEFAULT '', canonical_url text NOT NULL DEFAULT '', adsense_client text NOT NULL DEFAULT '', homepage_slot text NOT NULL DEFAULT '', article_slot text NOT NULL DEFAULT '', sidebar_slot text NOT NULL DEFAULT '');
GRANT SELECT ON public.site_settings TO anon; GRANT SELECT,INSERT,UPDATE ON public.site_settings TO authenticated; GRANT ALL ON public.site_settings TO service_role; ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY settings_read ON public.site_settings FOR SELECT TO anon,authenticated USING(true); CREATE POLICY settings_manage ON public.site_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'super_admin')) WITH CHECK(public.has_role(auth.uid(),'super_admin'));
CREATE TABLE public.submission_limits (key text PRIMARY KEY, count integer NOT NULL DEFAULT 1, window_start timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.submission_limits TO service_role; ALTER TABLE public.submission_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.consume_submission_limit(_key text,_max integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.submission_limits(key,count,window_start) VALUES(_key,1,now()) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN submission_limits.window_start < now()-interval '1 hour' THEN 1 ELSE submission_limits.count+1 END, window_start=CASE WHEN submission_limits.window_start < now()-interval '1 hour' THEN now() ELSE submission_limits.window_start END RETURNING count INTO n; RETURN n<=_max; END $$;
REVOKE ALL ON FUNCTION public.consume_submission_limit(text,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.consume_submission_limit(text,integer) TO service_role;
CREATE POLICY staff_image_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='article-images' AND public.is_staff()); CREATE POLICY staff_image_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='article-images' AND public.is_staff() AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp')); CREATE POLICY staff_image_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='article-images' AND public.is_staff());
CREATE FUNCTION public.article_timestamps() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); IF NEW.status='published' AND NEW.published_at IS NULL THEN NEW.published_at=now(); END IF; RETURN NEW; END $$;
CREATE TRIGGER article_timestamp BEFORE INSERT OR UPDATE ON public.articles FOR EACH ROW EXECUTE FUNCTION public.article_timestamps();
